"""Trust at scale: a run manifest, a determinism harness and a golden check (lessons 10.2.4-10.2.5, 12.3.3).

A plan is identified by the sha256 of its canonical JSON (status and starts), so two runs agree
exactly when their digests do. The manifest records what a run depended on: the export's hash,
the scenario, the solver and its settings, and the plan's digest. The golden file is a reviewed
plan for a fixed export; a change in the code that changes that plan fails the check until someone
reviews the new plan and writes it as the new golden.
"""

from __future__ import annotations

import hashlib
import json
from dataclasses import dataclass
from pathlib import Path

import ortools

from .data import load_request
from .plan import Plan
from .scenario import Scenario, apply
from .solve import PARAMS, solve
from .store import canonical, content_hash


def plan_digest(plan: Plan) -> str:
    body = canonical({"status": plan.status, "starts": plan.starts})
    return hashlib.sha256(body.encode("utf-8")).hexdigest()


def manifest(raw: dict, scenario: Scenario, plan: Plan) -> dict:
    return {
        "input": content_hash(raw),
        "scenario": scenario.to_dict(),
        "solver": {"name": "HIGHS", "ortools": ortools.__version__,
                   "threads": PARAMS.highs.int_options["threads"]},
        "plan": plan_digest(plan),
        "npv": round(plan.npv, 2),
    }


@dataclass(frozen=True)
class Harness:
    digests: list[str]

    @property
    def same(self) -> bool:
        return len(self.digests) > 1 and len(set(self.digests)) == 1


def harness(raw: dict, runs: int = 3, scenario: Scenario = Scenario("base")) -> Harness:
    """Plan the same export `runs` times from scratch and keep each plan's digest."""
    return Harness([plan_digest(solve(apply(load_request(raw), scenario))) for _ in range(runs)])


def write_golden(raw: dict, path: str | Path) -> None:
    plan = solve(load_request(raw))
    Path(path).write_text(json.dumps({"input": content_hash(raw), "status": plan.status, "npv": plan.npv,
                                      "starts": plan.starts}, indent=1, sort_keys=True) + "\n", encoding="utf-8")


def check_golden(raw: dict, path: str | Path) -> list[str]:
    """Every way today's plan of `raw` differs from the golden one; empty when they agree."""
    golden = json.loads(Path(path).read_text(encoding="utf-8"))
    if golden["input"] != content_hash(raw):
        return [f"input changed: golden {golden['input'][:12]}, now {content_hash(raw)[:12]}"]
    plan = solve(load_request(raw))
    found = [] if plan.status == golden["status"] else [f"status {golden['status']} -> {plan.status}"]
    for pid in sorted(set(golden["starts"]) | set(plan.starts)):
        before, now = golden["starts"].get(pid), plan.starts.get(pid)
        if before != now:
            found.append(f"{pid}: start {before} -> {now}")
    if abs(plan.npv - golden["npv"]) > 0.5:
        found.append(f"npv {golden['npv']:,.0f} -> {plan.npv:,.0f}")
    return found


def warm_solve(raw: dict, previous: Plan) -> Plan:
    """Plan `raw` starting from last cycle's plan."""
    return solve(load_request(raw), previous=previous)

"""The planning export, read into typed records.

The planners' export carries every column the planning system keeps (cost profiles, windows,
rules, NPV by start year, asset health). This version reads only the columns it uses and ignores
the rest, so the same export file serves every version of the planner.
"""

from __future__ import annotations

import json
from dataclasses import dataclass, field
from pathlib import Path


@dataclass(frozen=True)
class Asset:
    """The equipment a project works on: its age now, its Weibull curve and what a failure costs."""

    asset_id: str
    age: int                        # years, at the start of the plan's first year
    weibull_beta: float             # shape
    weibull_eta: float              # scale, years
    cof: int                        # $k, the consequence of one failure


@dataclass(frozen=True)
class Project:
    """One candidate project, as this version of the planner sees it."""

    project_id: str
    name: str
    cost_profile: tuple[int, ...]   # $k spent in each year of work, from the start year on
    npv: dict[int, int]             # $k, the NPV finance quotes for each start year
    asset: Asset
    earliest_start: int
    latest_start: int
    must_do: bool = False
    parent: str | None = None       # a project that must have started `parent_lag` years before
    parent_lag: int = 0
    alt_group: str | None = None    # at most one project of a group is funded
    bundle: str | None = None       # every project of a bundle is funded, or none

    @property
    def value(self) -> int:
        """The NPV of a start in the earliest year: what the planner used before lesson 14.2.4."""
        return self.npv[self.earliest_start]

    @property
    def capex(self) -> int:
        return sum(self.cost_profile)

    @property
    def duration(self) -> int:
        return len(self.cost_profile)

    def spend(self, start: int) -> dict[int, int]:
        """What the project spends in each calendar year if it starts in `start`."""
        return {start + k: amount for k, amount in enumerate(self.cost_profile)}


@dataclass(frozen=True)
class Request:
    """What the planners ask for: the projects, the years, and each year's budget."""

    name: str
    years: tuple[int, ...]
    budget: dict[int, int]          # $k available in each year
    projects: tuple[Project, ...]
    objective: str = "npv"          # "npv" or "risk": what the plan maximizes
    risk_floor: float | None = None  # $k: the least risk reduction a plan must deliver
    force_in: tuple[str, ...] = ()   # overrides from a scenario (lesson 14.2.7)
    force_out: tuple[str, ...] = ()
    fix_start: dict[str, int] = field(default_factory=dict)

    def project(self, project_id: str) -> Project:
        for p in self.projects:
            if p.project_id == project_id:
                return p
        raise KeyError(project_id)

    def groups(self, column: str) -> dict[str, list[str]]:
        """Projects sharing a value of `column` ("alt_group" or "bundle"), by that value, in id order."""
        found: dict[str, list[str]] = {}
        for p in self.projects:
            if getattr(p, column) is not None:
                found.setdefault(getattr(p, column), []).append(p.project_id)
        return {g: sorted(members) for g, members in sorted(found.items())}

    def starts(self, project: Project) -> range:
        """The project's window, cut so that its work starts and ends inside the plan's years."""
        first = max(project.earliest_start, self.years[0])
        last = min(project.latest_start, self.years[-1] - project.duration + 1)
        return range(first, last + 1)


def load_request(raw: dict) -> Request:
    """Build a Request from the export's dictionary form, refusing duplicate project ids."""
    projects = tuple(
        Project(
            project_id=row["id"],
            name=row["name"],
            cost_profile=tuple(row["cost_profile"]),
            npv={int(t): v for t, v in row["npv"].items()},
            asset=Asset(row["asset"]["id"], row["asset"]["age"], row["asset"]["weibull_beta"],
                        row["asset"]["weibull_eta"], row["asset"]["cof"]),
            earliest_start=row["earliest_start"],
            latest_start=row["latest_start"],
            must_do=row["must_do"],
            parent=row["parent"],
            parent_lag=row["parent_lag"],
            alt_group=row["alt_group"],
            bundle=row["bundle"],
        )
        for row in raw["projects"]
    )
    ids = [p.project_id for p in projects]
    if len(set(ids)) != len(ids):
        raise ValueError("duplicate project ids in the export")
    for p in projects:
        if p.parent is not None and p.parent not in ids:
            raise ValueError(f"{p.project_id} names an unknown parent {p.parent}")
    objective = raw.get("objective", "npv")
    if objective not in ("npv", "risk"):
        raise ValueError(f"unknown objective {objective!r}")
    return Request(name=raw["name"], years=tuple(raw["years"]),
                   budget={int(y): v for y, v in raw["budget"].items()}, projects=projects,
                   objective=objective, risk_floor=raw.get("risk_floor"))


def read_request(path: str | Path) -> Request:
    """Read an export file (JSON) into a Request."""
    return load_request(json.loads(Path(path).read_text(encoding="utf-8")))

"""Why a request has no plan, and why a project was left out of one.

Both answers name rows, because every row has the name its rule gave it (lesson 14.2.3). A
deletion filter (lesson 9.1.3) relaxes one row at a time and keeps it relaxed while the model stays
infeasible; the rows it cannot relax form an irreducible conflict: drop any one of them and a plan
exists. Forcing a deferred project in (lesson 9.3.2) prices the decision, or, when forcing it in is
infeasible, finds the rows that block it.
"""

from __future__ import annotations

import math
from dataclasses import dataclass

from .data import Request
from .model import Built, build
from .solve import run_highs, solve_built


@dataclass(frozen=True)
class Conflict:
    rows: list[str]
    message: str


@dataclass(frozen=True)
class Deferral:
    project: str
    npv_cost: float                 # $k of NPV the plan gives up to fund the project
    displaced: tuple[str, ...]      # funded in the plan, dropped when the project is forced in
    conflict: Conflict | None       # the rows that make forcing it in impossible


def feasible(built: Built) -> bool:
    return run_highs(built.model).termination.reason.name != "INFEASIBLE"


def deletion_filter(built: Built, keep: tuple[str, ...] = ()) -> list[str]:
    """An irreducible set of rows that cannot all hold; rows in `keep` are never relaxed."""
    for name in sorted(built.rows):
        if name in keep:
            continue
        row = built.rows[name]
        bounds = (row.lower_bound, row.upper_bound)
        row.lower_bound, row.upper_bound = -math.inf, math.inf
        if feasible(built):
            row.lower_bound, row.upper_bound = bounds          # needed for the clash: restore it
    return sorted(n for n, r in built.rows.items() if (r.lower_bound, r.upper_bound) != (-math.inf, math.inf))


def describe(request: Request, name: str) -> str:
    """One row, in the planners' words."""
    kind, _, rest = name.partition("_")
    if kind == "budget":
        return f"spend in {rest} within ${request.budget[int(rest)]:,}k"
    if kind == "must":
        return f"{rest} is a must-do"
    if kind == "force":
        return f"{rest} is forced in"
    if kind == "alt":
        return f"at most one of {', '.join(request.groups('alt_group')[rest])}"
    if kind == "bundle":
        return f"{' and '.join(rest.split('_'))} are funded together or not at all"
    if kind == "after":
        child, year = rest.split("_")
        c = request.project(child)
        return f"{child} started by {year} needs {c.parent} started by {int(year) - c.parent_lag}"
    if kind == "in":
        return f"the scenario funds {rest}"
    if kind == "out":
        return f"the scenario leaves {rest} out"
    if kind == "fix":
        pid, year = rest.split("_")
        return f"the scenario starts {pid} in {year}"
    if kind == "risk":
        return f"remove at least ${request.risk_floor:,.1f}k of risk"
    return name


def explain(request: Request, rows: list[str]) -> Conflict:
    lines = [f"No plan meets these {len(rows)} rules together; drop or change any one of them:"]
    lines += [f"  {name}: {describe(request, name)}" for name in rows]
    return Conflict(rows, "\n".join(lines))


def why_infeasible(request: Request) -> Conflict | None:
    """None when the request has a plan; otherwise the rows that clash, and a message naming them."""
    built = build(request)
    if feasible(built):
        return None
    return explain(request, deletion_filter(built))


def why_deferred(request: Request, plan, project_id: str) -> Deferral:
    """What funding `project_id` would cost the plan, or which rows make it impossible."""
    built = build(request)
    built.add(f"force_{project_id}", built.started(project_id) == 1)
    forced = solve_built(built)
    if forced.status == "infeasible":
        rows = deletion_filter(built, keep=(f"force_{project_id}",))
        return Deferral(project_id, math.inf, (), explain(request, rows))
    displaced = tuple(p for p in plan.funded if p not in forced.starts)
    return Deferral(project_id, plan.npv - forced.npv, displaced, None)

"""The model: a start-year decision per project and year, and the rows the rules add."""

from __future__ import annotations

from dataclasses import dataclass, field

from ortools.math_opt.python import mathopt

from .data import Request
from .rules import RULES
from .value import coefficients


@dataclass
class Built:
    """A built model and the handles the rest of the planner needs to read it."""

    request: Request
    model: mathopt.Model
    x: dict[tuple[str, int], mathopt.Variable]
    rows: dict[str, mathopt.LinearConstraint] = field(default_factory=dict)
    npv: mathopt.LinearSum | None = None       # the plan's NPV, $k
    risk: mathopt.LinearSum | None = None      # the risk the plan removes, $k

    def add(self, name: str, row) -> None:
        """Add one named row; the name is how reports and diagnostics refer to it."""
        self.rows[name] = self.model.add_linear_constraint(row, name=name)

    def started(self, pid: str) -> mathopt.LinearSum:
        """1 if project `pid` starts in some year of its window, else 0."""
        return mathopt.fast_sum(v for (p, _), v in self.x.items() if p == pid)

    def started_by(self, pid: str, year: int) -> mathopt.LinearSum:
        """1 if project `pid` starts in `year` or earlier, else 0."""
        return mathopt.fast_sum(v for (p, t), v in self.x.items() if p == pid and t <= year)

    def spend_by_year(self) -> dict[int, mathopt.LinearSum]:
        """Each year's spend as an expression, with every project's cost spread over its years of work."""
        terms: dict[int, list] = {y: [] for y in self.request.years}
        for (pid, t), v in self.x.items():
            for year, amount in self.request.project(pid).spend(t).items():
                terms[year].append(amount * v)
        return {y: mathopt.fast_sum(ts) for y, ts in terms.items()}


def build(request: Request) -> Built:
    model = mathopt.Model(name=request.name)
    x = {(p.project_id, t): model.add_binary_variable(name=f"x_{p.project_id}_{t}")
         for p in request.projects for t in request.starts(p)}
    built = Built(request, model, x)
    value = coefficients(request)
    built.npv = mathopt.fast_sum(value[key][0] * v for key, v in x.items())
    built.risk = mathopt.fast_sum(value[key][1] * v for key, v in x.items())
    for rule in RULES:
        rule(built)
    model.maximize(built.npv if request.objective == "npv" else built.risk)
    return built

"""The plan as the planners read it."""

from __future__ import annotations

from .data import Request
from .plan import Plan


def spend_by_year(request: Request, plan: Plan) -> dict[int, int]:
    """What the plan spends in each year, from the funded projects' starts and cost profiles."""
    spend = {y: 0 for y in request.years}
    for pid, start in plan.starts.items():
        for year, amount in request.project(pid).spend(start).items():
            spend[year] += amount
    return spend


def render(request: Request, plan: Plan) -> str:
    lines = [f"{request.name}: {plan.status}"]
    funded = [request.project(pid) for pid in plan.funded]
    capex = sum(p.capex for p in funded)
    lines.append(f"funded {len(funded)} of {len(request.projects)} projects, "
                 f"capex ${capex:,}k of ${sum(request.budget.values()):,}k, value ${plan.objective:,.0f}k")
    lines.append(f"NPV ${plan.npv:,.0f}k, risk reduced ${plan.risk:,.1f}k (maximized: {request.objective})")
    for year, spend in spend_by_year(request, plan).items():
        lines.append(f"  {year}  spend ${spend:,}k of ${request.budget[year]:,}k")
    for p in funded:
        start = plan.starts[p.project_id]
        lines.append(f"  {p.project_id}  start {start}  "
                     f"capex {p.capex:>6,}  npv {p.npv[start]:>6,}  {p.name}")
    return "\n".join(lines)

"""The planners' business rules, one function per rule, each adding rows with the names it owns.

Every rule reads the request and the start variables through `built` and adds its rows with
`built.add(name, row)`. A new rule is a new function added to RULES; `build` never changes.
"""

from __future__ import annotations

from typing import TYPE_CHECKING

from ortools.math_opt.python import mathopt

if TYPE_CHECKING:
    from .model import Built


def once_or_must(built: Built) -> None:
    """(once_i) a project starts at most once; (must_i) a must-do starts exactly once."""
    for p in built.request.projects:
        if p.must_do:
            built.add(f"must_{p.project_id}", built.started(p.project_id) == 1)
        else:
            built.add(f"once_{p.project_id}", built.started(p.project_id) <= 1)


def alternatives(built: Built) -> None:
    """(alt_g) at most one project of an alternative group is funded."""
    for group, members in built.request.groups("alt_group").items():
        built.add(f"alt_{group}", mathopt.fast_sum(built.started(m) for m in members) <= 1)


def bundles(built: Built) -> None:
    """(bundle_{b,j}) each member of a bundle is funded exactly when its first member is."""
    for members in built.request.groups("bundle").values():
        first = members[0]
        for j in members[1:]:
            built.add(f"bundle_{first}_{j}", built.started(j) - built.started(first) == 0)


def parents(built: Built) -> None:
    """(after_{c,t}) a child started by year t needs its parent started by year t - lag."""
    request = built.request
    for c in request.projects:
        if c.parent is None:
            continue
        parent = request.project(c.parent)
        for t in request.starts(c):
            built.add(f"after_{c.project_id}_{t}",
                      built.started_by(c.project_id, t) - built.started_by(parent.project_id, t - c.parent_lag)
                      <= 0)


def budgets(built: Built) -> None:
    """(budget_y) each year's spend, with costs spread over the years of work, within its budget."""
    for y, spend in built.spend_by_year().items():
        built.add(f"budget_{y}", spend <= built.request.budget[y])


def risk_floor(built: Built) -> None:
    """(risk_floor) the plan removes at least the floor the planners set, when they set one."""
    if built.request.risk_floor is not None:
        built.add("risk_floor", built.risk >= built.request.risk_floor)


def overrides(built: Built) -> None:
    """(in_i) (out_i) (fix_{i,t}) a scenario's overrides, as named rows the diagnostics can name."""
    request = built.request
    for pid in request.force_in:
        built.add(f"in_{pid}", built.started(pid) == 1)
    for pid in request.force_out:
        built.add(f"out_{pid}", built.started(pid) == 0)
    for pid, year in sorted(request.fix_start.items()):
        built.add(f"fix_{pid}_{year}", built.started_by(pid, year) - built.started_by(pid, year - 1) == 1)


RULES = (once_or_must, alternatives, bundles, parents, budgets, risk_floor, overrides)

"""Scenarios: what planners change before a run, kept as data beside the export they change.

A scenario never edits the export. It names budget changes and overrides, and `apply` turns them
into a new Request; the overrides become named rows (rules.overrides), so the diagnostics of lesson
14.2.6 can name an override that clashes with a rule. `diff` compares two plans (lesson 9.3.3).
"""

from __future__ import annotations

from dataclasses import asdict, dataclass, field, replace

from .data import Request
from .plan import Plan


@dataclass(frozen=True)
class Scenario:
    name: str
    budget: dict[int, int] = field(default_factory=dict)      # year -> $k, replaces that year's budget
    force_in: tuple[str, ...] = ()
    force_out: tuple[str, ...] = ()
    fix_start: dict[str, int] = field(default_factory=dict)   # project -> the year it must start
    note: str = ""                                            # why: the audit trail's one line

    def to_dict(self) -> dict:
        data = asdict(self)
        data["budget"] = {str(y): v for y, v in self.budget.items()}
        return {**data, "force_in": list(self.force_in), "force_out": list(self.force_out)}

    @classmethod
    def from_dict(cls, data: dict) -> "Scenario":
        return cls(name=data["name"], budget={int(y): v for y, v in data["budget"].items()},
                   force_in=tuple(data["force_in"]), force_out=tuple(data["force_out"]),
                   fix_start=dict(data["fix_start"]), note=data["note"])


def apply(request: Request, scenario: Scenario) -> Request:
    """The request with the scenario's budgets and overrides; refuses projects the export lacks."""
    named = set(scenario.force_in) | set(scenario.force_out) | set(scenario.fix_start)
    unknown = sorted(named - {p.project_id for p in request.projects})
    if unknown:
        raise ValueError(f"scenario {scenario.name} names unknown projects: {', '.join(unknown)}")
    return replace(request, name=f"{request.name} / {scenario.name}",
                   budget={**request.budget, **scenario.budget},
                   force_in=scenario.force_in, force_out=scenario.force_out, fix_start=dict(scenario.fix_start))


@dataclass(frozen=True)
class Diff:
    selected: tuple[str, ...]                   # funded in the other plan only
    deferred: tuple[str, ...]                   # funded in the base plan only
    shifted: tuple[tuple[str, int, int], ...]   # (project, base start, other start)


def diff(base: Plan, other: Plan) -> Diff:
    return Diff(
        selected=tuple(p for p in other.funded if p not in base.starts),
        deferred=tuple(p for p in base.funded if p not in other.starts),
        shifted=tuple((p, base.starts[p], other.starts[p]) for p in base.funded
                      if p in other.starts and other.starts[p] != base.starts[p]),
    )

"""What a start is worth: NPV by start year, and the failure risk the work removes.

NPV comes from finance, one figure per start year (lesson 7.2.4). Risk is computed here from the
asset's Weibull curve (lesson 7.3.1) and its consequence of failure (lesson 7.3.3): the work removes
the asset's yearly risk, PoF x CoF, from the year after the work ends to the plan's last year
(lesson 7.3.4).
"""

from __future__ import annotations

import math

from .data import Project, Request


def annual_pof(beta: float, eta: float, age: float) -> float:
    """The chance an asset of this age fails within the next year, given that it has not failed yet."""
    return 1.0 - math.exp((age / eta) ** beta - ((age + 1) / eta) ** beta)


def annual_risk(request: Request, project: Project, year: int) -> float:
    """Expected failure cost of the project's asset in `year` if nothing is done ($k)."""
    a = project.asset
    return a.cof * annual_pof(a.weibull_beta, a.weibull_eta, a.age + year - request.years[0])


def risk_reduction(request: Request, project: Project, start: int) -> float:
    """Risk removed by a start in `start`: every year after the work ends, to the plan's last year."""
    return sum(annual_risk(request, project, y) for y in range(start + project.duration, request.years[-1] + 1))


def coefficients(request: Request) -> dict[tuple[str, int], tuple[int, float]]:
    """(npv, risk reduction) for every project and start year the model has a variable for."""
    return {(p.project_id, t): (p.npv[t], risk_reduction(request, p, t))
            for p in request.projects for t in request.starts(p)}

